window.DALAT_PLACES = [{"id":"5S01","name":"Dalat Palace Heritage Hotel","group":"Khách sạn/Resort 5 sao","category":"5s","type":"Khách sạn","star":"5 sao","address":"Số 02 Trần Phú, Phường 3, Thành phố Đà Lạt","lat":11.9405,"lng":108.4357,"maps":"https://maps.app.goo.gl/fuA3i5RSey3YQvst5","description":"Dalat Palace Heritage Hotel (tiền thân là Langbian Palace) tọa lạc tại số 2 đường Trần Phú, trung tâm thành phố Đà Lạt và nhìn ra hồ Xuân Hương.\nMở cửa từ năm 1922, đây là một biểu tượng kiến trúc Pháp cổ điển kết hợp phong cách Art Deco danh tiếng bậc nhất cao nguyên. Khách sạn 5 sao này gồm 73 phòng nghỉ (43 phòng cổ điển và 30 phòng hiện đại), nằm trong khuôn viên xanh mát rộng gần 5,5 héc-ta.\nKhông gian nơi đây mang đậm dấu ấn hoài niệm với nội thất thủ công tinh xảo, lò sưởi củi cổ điển, kết hợp các dịch vụ cao cấp như nhà hàng Pháp Le Rabelais, tiệc trà chiều, spa thư giãn và câu lạc bộ golf 18 lỗ kế cận.","expectedPhotoFiles":["5S01_01.jpg","5S01_02.jpg","5S01_03.jpg"],"photos":["data:image/jpeg;base64,","data:image/jpeg;base64,"],"notes":["Đã đưa 2 ảnh do người dùng cung cấp vào bản đồ.","Tọa độ lấy từ bảng khảo sát, chưa xác minh độc lập vị trí thực tế."]},{"id":"5S02","name":"MerPerle Dalat Hotel","group":"Khách sạn/Resort 5 sao","category":"5s","type":"Khách sạn","star":"5 sao","address":"Số 01 Hùng Vương, Phường 10, Thành phố Đà Lạt","lat":11.940962,"lng":108.45916,"maps":"https://maps.app.goo.gl/Ctfqv1SDeHEp93ao7","description":"Khách sạn MerPerle Đà Lạt là biểu tượng nghỉ dưỡng 5 sao bề thế và xa hoa bậc nhất tại thành phố ngàn hoa. Tọa lạc tại số 1 Hùng Vương, Phường 10, khách sạn sở hữu kiến trúc bán cổ điển Châu Âu nguy nga như một tòa lâu đài, kiêu hãnh ôm trọn tầm nhìn ra những đồi thông xanh mướt đặc trưng của vùng cao nguyên Đà Lạt.\nKhách sạn quy mô lớn này cung cấp hệ thống phòng nghỉ đẳng cấp từ hạng Deluxe tinh tế đến các căn Suite thượng lưu. Không gian bên trong được chăm chút tỉ mỉ với nội thất cao cấp và tông màu ấm áp, mang lại sự thư thái tuyệt đối cho du khách.\nĐiểm nhấn làm nên trải nghiệm thượng lưu tại MerPerle chính là chuỗi dịch vụ tiện ích toàn diện. Du khách có thể thưởng thức ẩm thực đa dạng từ Á sang Âu tại hệ thống nhà hàng sang trọng, hay thả mình trong làn nước ấm của hồ bơi bốn mùa trong nhà – một tiện ích hoàn hảo cho khí hậu se lạnh của Đà Lạt. Ngoài ra, trung tâm Spa & Wellness chuyên nghiệp và không gian sảnh lounge lộng lẫy phục vụ trà chiều sẽ là nơi lý tưởng để bạn tái tạo năng lượng và tận hưởng kỳ nghỉ trọn vẹn bên người thân.","expectedPhotoFiles":["5S02_01.jpg","5S02_02.jpg","5S02_03.jpg"],"photos":["data:image/jpeg;base64,","data:image/jpeg;base64,","data:image/jpeg;base64,"],"notes":["Đã đưa 3 ảnh do người dùng cung cấp vào bản đồ.","Tọa độ lấy từ bảng khảo sát, chưa xác minh độc lập vị trí thực tế."]},{"id":"5S03","name":"Best Western Premier Imperial Dalat","group":"Khách sạn/Resort 5 sao","category":"5s","type":"Khách sạn","star":"5 sao","address":"Số 57–59 Hùng Vương, Phường 10, Thành phố Đà Lạt.","lat":11.9421,"lng":108.4682,"maps":"https://maps.app.goo.gl/aktQoh8jJn1J9Ssb7","description":"Khách sạn Best Western Premier Imperial Đà Lạt là biểu tượng nghỉ dưỡng 5 sao quốc tế đẳng cấp, tọa lạc tại số 57-59 Hùng Vương, Phường 10. Nơi đây gây ấn tượng mạnh mẽ nhờ sự kết hợp hài hòa giữa kiến trúc Indochine thanh lịch và nét tân cổ điển sang trọng, tạo nên một không gian hoài cổ, trang nhã giữa lòng phố núi.\nVới quy mô đồ sộ gần 500 phòng nghỉ và căn hộ cao cấp, khách sạn mang đến không gian lưu trú ấm cúng, tinh tế. Hầu hết các hạng phòng tại đây đều sở hữu ban công riêng mở ra tầm nhìn bao quát hướng thung lũng sương mù hoặc toàn cảnh thành phố thơ mộng.\nTrải nghiệm thượng lưu của du khách được hoàn thiện bởi chuỗi tiện ích đa dạng: thưởng thức ẩm thực Á-Âu tại hệ thống nhà hàng quý phái, thư giãn bên ly cocktail tại quầy bar, hay thả mình trong hồ bơi bốn mùa nước ấm trong nhà thích hợp với khí hậu se lạnh. Ngoài ra, khách sạn còn tích hợp khu vui chơi trẻ em, vườn Nhật Bản, phòng gym và trung tâm Spa hiện đại, đáp ứng trọn vẹn nhu cầu nghỉ dưỡng của mọi gia đình.","expectedPhotoFiles":["5S03_01.jpg","5S03_02.jpg","5S03_03.jpg"],"photos":["data:image/jpeg;base64,","data:image/jpeg;base64,","data:image/jpeg;base64,"],"notes":["Đã đưa 3 ảnh do người dùng cung cấp vào bản đồ.","Tọa độ lấy từ bảng khảo sát, chưa xác minh độc lập vị trí thực tế."]},{"id":"5S04","name":"Dalat Edensee Lake Resort & Spa","group":"Khách sạn/Resort 5 sao","category":"5s","type":"Resort","star":"5 sao","address":"Khu chức năng VII.2, Khu du lịch Hồ Tuyền Lâm, Phường 3, Thành phố Đà Lạt","lat":11.8906,"lng":108.4357,"maps":"https://maps.app.goo.gl/giNkMzGMNv54cGJ59","description":"Dalat Edensee Lake Resort & Spa là khu nghỉ dưỡng 5 sao ẩn mình biệt lập trên một bán đảo thơ mộng thuộc khu du lịch Hồ Tuyền Lâm. Được bao bọc bởi ba mặt hồ tĩnh lặng và những cánh rừng thông ngút ngàn, nơi đây mang đến không gian an yên tuyệt đối cho những ai muốn tìm kiếm một kỳ nghỉ chữa lành.\nResort sở hữu phong cách kiến trúc Bavarian của Đức cổ kính và thanh lịch. Hệ thống biệt thự sang trọng tại đây được chia thành các phân khu mang tên loài hoa như Jasmine, Camellia hay Mimosa, cung cấp ban công rộng lớn mở ra tầm nhìn toàn cảnh thung lũng sương mù hoặc mặt hồ phẳng lặng.\nĐiểm nhấn thượng lưu của Edensee là trung tâm La Roseraie Spa rộng 2.000m² với các liệu pháp thủy trị liệu chuyên sâu và hồ bơi nước ấm trong nhà trực diện hướng hồ. Ngoài ra, du khách còn được trải nghiệm chuỗi hoạt động thú vị như chèo thuyền kayak, bắn cung, tham quan khu nuôi chim công hay thưởng thức ẩm thực tinh tế tại hệ thống nhà hàng chuẩn quốc tế.","expectedPhotoFiles":["5S04_01.jpg","5S04_02.jpg","5S04_03.jpg"],"photos":["data:image/jpeg;base64,","data:image/jpeg;base64,","data:image/jpeg;base64,"],"notes":["Đã đưa 3 ảnh do người dùng cung cấp vào bản đồ.","Tọa độ lấy từ bảng khảo sát, chưa xác minh độc lập vị trí thực tế."]},{"id":"5S05","name":"Ana Mandara Villas Dalat Resort & Spa","group":"Khách sạn/Resort 5 sao","category":"5s","type":"Resort","star":"5 sao","address":"Đường Lê Lai, Phường 5, Thành phố Đà Lạt","lat":11.9472,"lng":108.4281,"maps":"https://maps.app.goo.gl/Dff1vNV7UiYWTfeHA","description":"Ana Mandara Villas Dalat Resort & Spa là khu nghỉ dưỡng 5 sao độc nhất vô nhị, tọa lạc tại đường Lê Lai, Phường 5. Nơi đây như một ngôi làng Pháp cổ kính ẩn hiện giữa rừng thông già tuổi đời trăm năm, mang đến không gian lưu trú mang đậm dấu ấn lịch sử, lãng mạn và hoàn toàn tách biệt khỏi sự ồn ào của phố thị.\nResort sở hữu 17 căn biệt thự di sản với 87 phòng nghỉ được phục dựng nguyên vẹn từ kiến trúc Đông Dương những năm 1920 - 1930. Mỗi gian phòng là một kiệt tác nghệ thuật với sàn gỗ tự nhiên, lò sưởi củi bập bùng, bồn tắm chân rồng cổ điển và đồ nội thất gỗ cổ, mở ra tầm nhìn hướng ra những khu vườn xanh mướt đầy hoa.\nTrải nghiệm tại Ana Mandara được nâng tầm bởi hồ bơi nước ấm ngoài trời duy nhất tại Đà Lạt, cho phép du khách thư giãn giữa tiết trời se lạnh. Bên cạnh đó, La Cochinchine Spa với các liệu pháp massage chuẩn Pháp và nhà hàng Le Petit Dalat phục vụ ẩm thực kiểu Pháp tinh tế sẽ mang lại kỳ nghỉ dưỡng hoàn hảo nhất.","expectedPhotoFiles":["5S05_01.jpg","5S05_02.jpg","5S05_03.jpg"],"photos":["data:image/jpeg;base64,"],"notes":["Đã đưa 1 ảnh do người dùng cung cấp vào bản đồ.","Tọa độ lấy từ bảng khảo sát, chưa xác minh độc lập vị trí thực tế."]},{"id":"5S06","name":"Grand Mercure Dala","group":"Khách sạn/Resort 5 sao","category":"5s","type":"Resort","star":"5 sao","address":"03 Nguyễn Du, Phường Lâm Viên (Phường 9 cũ), TP. Đà Lạt, Lâm Đồng.","lat":11.9452,"lng":108.4595,"maps":"https://share.google/dL7N0RIAEAmRzS15x","description":"Grand Mercure Dalat Resort là khu nghỉ dưỡng 5 sao đẳng cấp quốc tế thuộc tập đoàn Accor, tọa lạc tại số 03 Nguyễn Du, Phường 9, ngay gần Ga Đà Lạt lịch sử. Nơi đây hiện lên như một ốc đảo lãng mạn, tái hiện trọn vẹn nét thanh lịch của khu phố \"Pháp xưa\" giữa lòng cao nguyên.\nKhu nghỉ dưỡng được bao bọc bởi những vườn hồng rực rỡ và rừng thông xanh mát. Quy mô kiến trúc độc đáo gồm 12 căn biệt thự cổ điển kiểu Pháp đầu thế kỷ XX, cung cấp 131 phòng nghỉ và suite sang trọng. Không gian nội thất mang tông màu ấm áp lấy cảm hứng từ trường phái ấn tượng của Claude Monet, kết hợp hài hòa giữa di sản bản địa và sự tiện nghi hiện đại.\nTrải nghiệm thượng lưu tại đây được hoàn thiện bởi nhà hàng Deux Amants tinh tế, quầy bar Moon Lounge đầy phong cách, trung tâm La Maison Wellness Spa chuyên sâu, phòng gym 24/7 và một hồ bơi ngoài trời khoáng đạt.","expectedPhotoFiles":["5S06_01.jpg","5S06_02.jpg","5S06_03.jpg"],"photos":[],"notes":["Chưa có ảnh Đà Lạt đã đối chiếu mã cơ sở trong các lượt bổ sung hiện tại.","Tọa độ lấy từ bảng khảo sát, chưa xác minh độc lập vị trí thực tế."]},{"id":"5S07","name":"Tea Resort Prenn","group":"Khách sạn/Resort 5 sao","category":"5s","type":"Resort","star":"5 sao","address":"Chân đèo Prenn (Quốc lộ 20), Thành phố Đà Lạt","lat":11.8767,"lng":108.4554,"maps":"https://maps.app.goo.gl/1AZAqe9fzm5Eh9n2A","description":"Tea Resort Prenn là khu nghỉ dưỡng đẳng cấp tọa lạc ngay cửa ngõ thành phố tại chân đèo Prenn, Phường 3. Được ví như \"vườn địa đàng\" giữa đại ngàn, resort ôm trọn khuôn viên rộng lớn bao quanh thác Prenn tự nhiên hoang sơ và men theo triền núi Phượng Hoàng linh thiêng.\nNơi đây sở hữu hệ thống phòng nghỉ và biệt thự sang trọng có gam màu trầm ấm cúng. Các căn villa mang thiết kế hiện đại, tinh tế với tầm nhìn biệt lập hướng ra rừng thông nguyên sinh mờ sương hoặc hồ tạo sóng xanh mát.\nĐiểm độc đáo tạo nên thương hiệu của Tea Resort Prenn là sự kết hợp hoàn hảo giữa nghỉ dưỡng sinh thái, giải trí và tâm linh. Du khách có thể hành hương chiêm bái tại quần thể Đền Hùng Tây Nguyên trên đỉnh núi, thỏa sức vui chơi tại biển nhân tạo trên cao nguyên hay khu trò chơi cảm giác mạnh. Tiện ích được hoàn thiện với không gian trà đạo, trung tâm Tea Spa phục vụ trị liệu chuyên sâu và nhà hàng Atisô mang đến trải nghiệm ẩm thực đa dạng.","expectedPhotoFiles":["5S07_01.jpg","5S07_02.jpg","5S07_03.jpg"],"photos":[],"notes":["Chưa có ảnh Đà Lạt đã đối chiếu mã cơ sở trong các lượt bổ sung hiện tại.","Tọa độ lấy từ bảng khảo sát, chưa xác minh độc lập vị trí thực tế."]},{"id":"4S01","name":"Hotel Colline","group":"Khách sạn 4 sao","category":"4s","type":"Khách sạn","star":"4 sao","address":"0 Phan Bội Châu, Phường 2, TP. Đà Lạt","lat":11.9438,"lng":108.4384,"maps":"https://maps.app.goo.gl/wBKc3hyyY3hipfPw9","description":"Hotel Colline Đà Lạt là khách sạn 4 sao hiện đại và sầm uất bậc nhất, tọa lạc tại số 10 Phan Bội Châu, Phường 1, ngay trung tâm khu phức hợp Dalat Center. Với vị trí đắc địa này, du khách chỉ mất vài bước chân để đi bộ ra Chợ đêm Đà Lạt và Hồ Xuân Hương thơ mộng.\nKhách sạn nổi bật với kiến trúc hình khối phá cách độc đáo, mang sắc nâu gạch ấm áp và hiện đại như một góc phố Tây Âu. Colline sở hữu 150 phòng nghỉ thiết kế theo phong cách tối giản thanh lịch, tối ưu hóa công năng và đều có cửa sổ kính lớn mở ra tầm nhìn bao quát toàn cảnh thành phố nhộn nhịp.\nNơi đây là thiên đường dịch vụ với trung tâm ẩm thực đa dạng: từ nhà hàng Salt & Pepper phục vụ buffet quốc tế, quầy bánh ngọt Central Bakery đến nhà hàng Nhật Bản Soy. Các tiện ích Gym, Spa hiện đại và Sky Bar tầng thượng lộng gió cũng sẵn sàng mang lại trải nghiệm tiện nghi, trẻ trung cho du khách.","expectedPhotoFiles":["4S01_01.jpg","4S01_02.jpg","4S01_03.jpg"],"photos":["data:image/jpeg;base64,","data:image/jpeg;base64,","data:image/jpeg;base64,"],"notes":["Đã đưa 3 ảnh do người dùng cung cấp vào bản đồ.","Tọa độ lấy từ bảng khảo sát, chưa xác minh độc lập vị trí thực tế."]},{"id":"4S02","name":"Nesta Valley Dalat","group":"Khách sạn 4 sao","category":"4s","type":"Khách sạn","star":"4 sao","address":"Số 94 Bùi Thị Xuân, Phường 2, TP. Đà Lạt","lat":11.9486,"lng":108.4419,"maps":"https://maps.app.goo.gl/t1tZFdiLbwcY6fpE9","description":"Nesta Valley Dalat Hotel (tên gọi cũ là Golf Valley Hotel) là khách sạn 4 sao hiện đại, tọa lạc tại số 94 Bùi Thị Xuân, Phường 2, ngay trung tâm thành phố và cách Chợ Đà Lạt chỉ khoảng 10 phút đi bộ.\nKhách sạn gây ấn tượng mạnh mẽ với lối kiến trúc gấp nếp đương đại độc đáo bên ngoài, kết hợp hài hòa cùng phong cách thiết kế Bắc Âu tinh tế, ấm cúng bên trong. Nesta Valley sở hữu 164 phòng nghỉ sang trọng, tất cả đều được tích hợp ban công riêng mở ra tầm nhìn thoáng đãng hướng về trung tâm phố núi nhộn nhịp hoặc thung lũng mờ sương.\nTrải nghiệm lưu trú tại đây được hoàn thiện trọn vẹn nhờ chuỗi tiện ích đa dạng: nhà hàng Valley Cafe phục vụ buffet Á-Âu phong phú, Mimosa Bar sôi động, phòng Gym hiện đại cùng trung tâm Nesta Spa rộng lớn mang đến các liệu pháp chăm sóc sức khỏe chuyên sâu.","expectedPhotoFiles":["4S02_01.jpg","4S02_02.jpg","4S03_03.jpg"],"photos":["data:image/jpeg;base64,","data:image/jpeg;base64,"],"notes":["Đã đưa 2 ảnh do người dùng cung cấp vào bản đồ.","Tọa độ lấy từ bảng khảo sát, chưa xác minh độc lập vị trí thực tế."]},{"id":"4S03","name":"Duparc Hotel Dalat","group":"Khách sạn 4 sao","category":"4s","type":"Khách sạn","star":"4 sao","address":"Số 15 Trần Phú, Phường 3, TP. Đà Lạt","lat":11.937,"lng":108.4391,"maps":"https://maps.app.goo.gl/AzBqha9DhLn976ET6","description":"Duparc Hotel Dalat là một trong những khách sạn 4 sao lâu đời và giàu giá trị di sản nhất tại thành phố ngàn hoa, tọa lạc tại số 15 Trần Phú, Phường 3. Được xây dựng từ năm 1932, công trình sở hữu lối kiến trúc Belle Époque tân cổ điển Pháp đầy quý phái, mang đến cho du khách một tấm vé ngược dòng thời gian về thời kỳ hoàng kim của Đà Lạt xưa.\nKhách sạn cung cấp hệ thống phòng nghỉ thanh lịch với nội thất gỗ ấm cúng, kết hợp tinh tế giữa nét hoài cổ và các tiện nghi hiện đại. Đặc biệt, du khách sẽ được trải nghiệm chiếc thang máy cổ bằng gỗ nguyên bản từ thập niên 1930 độc nhất vô nhị vẫn còn hoạt động.\nKhông gian ẩm thực tại đây nổi bật với nhà hàng Le Bistro phục vụ các món Pháp tinh tế, cùng quán cà phê Le Select Bar lãng mạn. Với vị trí đắc địa ngay trung tâm, từ khách sạn, bạn có thể dễ dàng đi bộ đến Nhà thờ Con Gà và Hồ Xuân Hương.","expectedPhotoFiles":["4S03_01.jpg","4S03_02.jpg","4S03_03.jpg"],"photos":["data:image/jpeg;base64,","data:image/jpeg;base64,"],"notes":["Đã đưa 2 ảnh do người dùng cung cấp vào bản đồ.","Tọa độ lấy từ bảng khảo sát, chưa xác minh độc lập vị trí thực tế."]},{"id":"4S04","name":"TTC Hotel - Ngọc Lan","group":"Khách sạn 4 sao","category":"4s","type":"Khách sạn","star":"4 sao","address":"Số 42 Nguyễn Chí Thanh, Phường 1, TP. Đà Lạt","lat":11.9429,"lng":108.4367,"maps":"https://maps.app.goo.gl/VLNV8vTA4wNi91zx9","description":"TTC Hotel - Ngọc Lan là khách sạn 4 sao danh tiếng mang tính biểu tượng, tọa lạc đắc địa tại số 42 Nguyễn Chí Thanh, Phường 1. Nằm ngay trên đồi cao giữa trung tâm, khách sạn sở hữu vị trí lý tưởng khi chỉ cách Chợ đêm Đà Lạt vài bước chân và mở ra tầm nhìn trực diện tuyệt đẹp xuống Hồ Xuân Hương thơ mộng.\nKhách sạn nổi bật với tòa nhà màu trắng muốt mang phong cách kiến trúc Châu Âu thanh lịch. Quy mô gồm 91 phòng nghỉ và Suite sang trọng, nổi bật với sàn gỗ cao cấp và tông màu tím trang nhã kết hợp sắc vàng ấm cúng, tạo nên không gian vô cùng lãng mạn giữa tiết trời phố núi. Hầu hết các phòng đều có cửa sổ kính lớn hướng hồ hoặc hướng phố nhộn nhịp.\nTrải nghiệm của du khách được hoàn thiện bởi nhà hàng Forget Me Not trên tầng thượng phục vụ ẩm thực Á-Âu đặc sắc, trung tâm Spa với 20 phòng trị liệu chuyên sâu, phòng Gym hiện đại và không gian sảnh café lãng mạn.","expectedPhotoFiles":["4S04_01.jpg","4S04_02.jpg","4S04_02.jpg"],"photos":["data:image/jpeg;base64,","data:image/jpeg;base64,","data:image/jpeg;base64,"],"notes":["Đã đưa 3 ảnh do người dùng cung cấp vào bản đồ.","Tọa độ lấy từ bảng khảo sát, chưa xác minh độc lập vị trí thực tế."]},{"id":"4S05","name":"Mường Thanh Holiday Đà Lạt","group":"Khách sạn 4 sao","category":"4s","type":"Khách sạn","star":"4 sao","address":"• Số 42 Phan Đình Phùng, Phường 1, TP. Đà Lạt.","lat":11.9443,"lng":108.4379,"maps":"https://maps.app.goo.gl/ybaELV3DEs1jkMGB9","description":"Mường Thanh Holiday Đà Lạt là khách sạn đạt tiêu chuẩn 4 sao danh tiếng, tọa lạc đắc địa tại số 42 Phan Bội Châu, Phường Xuân Hương. Với vị trí vàng ngay trung tâm phố núi, khách sạn chỉ cách Chợ Đà Lạt và Hồ Xuân Hương vài bước đi bộ, vô cùng thuận tiện cho hành trình vui chơi và khám phá ẩm thực của du khách.\nKhách sạn nổi bật với lối kiến trúc lấy cảm hứng từ những tòa lâu đài Pháp cổ kính, mang nét mộc mạc nhưng không kém phần thanh lịch. Quy mô gồm 71 phòng nghỉ hiện đại, được lót sàn gỗ ấm áp và thiết kế cửa sổ lớn hướng ra cảnh quan thiên nhiên trong lành hoặc thung lũng mờ sương đầy thơ mộng.\nTrải nghiệm tại đây được hoàn thiện tối đa nhờ chuỗi tiện ích đa dạng: hồ bơi nước ấm trong nhà mở cửa hàng ngày phù hợp với tiết trời se lạnh, trung tâm phục hồi sức khỏe Spa làm đẹp, phòng gym tiện nghi cùng hệ thống nhà hàng Xuân Hương chuyên phục vụ các món ăn Á - Âu và đặc sản Đà Lạt độc đáo.","expectedPhotoFiles":["4S05_01.jpg","4S05_02.jpg","4S05_03.jpg"],"photos":["data:image/jpeg;base64,","data:image/jpeg;base64,","data:image/jpeg;base64,","data:image/jpeg;base64,","data:image/jpeg;base64,","data:image/jpeg;base64,"],"notes":["Đã đưa 6 ảnh do người dùng cung cấp vào bản đồ.","Tọa độ lấy từ bảng khảo sát, chưa xác minh độc lập vị trí thực tế."]},{"id":"3S01","name":"Khách sạn Ngọc Phát Đà Lạt","group":"Khách sạn 3 sao","category":"3s","type":"Khách sạn","star":"3 sao","address":"Số 10 Đường Hồ Tùng Mậu, Phường 10, TP. Đà Lạt","lat":11.9385,"lng":108.4402,"maps":"https://share.google/F3ofajTq2W89x3vP6","description":"Khách sạn Ngọc Phát Đà Lạt là khách sạn đạt tiêu chuẩn 4 sao sang trọng, tọa lạc đắc địa tại số 10 Hồ Tùng Mậu, Phường 3. Với vị trí vàng ngay trung tâm, khách sạn nằm đối diện trực diện với quảng trường Lâm Viên sầm uất và chỉ cách Hồ Xuân Hương vài bước đi bộ, vô cùng thuận tiện cho việc tham quan và mua sắm.\nKhách sạn nổi bật với lối kiến trúc Châu Âu hiện đại và thanh lịch. Quy mô gồm 65 phòng nghỉ thiết kế tinh tế, ấm cúng với nội thất cao cấp. Điểm đắt giá nhất của Ngọc Phát là hơn một nửa số phòng sở hữu ban công hoặc cửa sổ kính lớn mở ra tầm nhìn panorama tuyệt đẹp bao trọn toàn cảnh hồ Xuân Hương thơ mộng hoặc đồi thông xanh mướt.\nTrải nghiệm của du khách được hoàn thiện nhờ hệ thống nhà hàng phục vụ thực đơn Á-Âu phong phú, quán cà phê sân vườn lãng mạn, dịch vụ phòng chu đáo và đội ngũ nhân viên thân thiện, chuyên nghiệp.","expectedPhotoFiles":["3S01_01.jpg","3S01_02.jpg","3S01_03.jpg"],"photos":["data:image/jpeg;base64,","data:image/jpeg;base64,","data:image/jpeg;base64,"],"notes":["Đã đưa 3 ảnh do người dùng cung cấp vào bản đồ.","Tọa độ lấy từ bảng khảo sát, chưa xác minh độc lập vị trí thực tế."]},{"id":"3S02","name":"Khách Sạn Iris Đà Lạt","group":"Khách sạn 3 sao","category":"3s","type":"Khách sạn","star":"3 sao","address":"Số 20 Đường Phan Như Thạch, Phường 1, TP. Đà Lạt","lat":11.9427,"lng":108.4354,"maps":"https://share.google/Ed7tlF5nNKEIMyc7M","description":"Iris Dalat Hotel là khách sạn đạt tiêu chuẩn 3 sao thanh lịch, tọa lạc tại số 20 Phan Như Thạch, Phường 1. Với vị trí đắc địa ngay trung tâm phố núi, nơi đây chỉ cách Chợ Đà Lạt và Hồ Xuân Hương khoảng 10 phút đi bộ, rất thuận tiện cho du khách dạo phố, trải nghiệm ẩm thực và mua sắm.\nKhách sạn nổi bật với lối kiến trúc được lấy cảm hứng từ những tòa nhà Pháp cổ kính, mang nét hiện đại, sang trọng nhưng vẫn vô cùng ấm cúng. Quy mô gồm 54 phòng nghỉ trải rộng trên 6 tầng, tất cả đều được trang bị nội thất gỗ tinh tế, đầy đủ tiện nghi thiết yếu và cửa sổ thoáng mát.\nĐến với Iris Dalat Hotel, trải nghiệm nghỉ dưỡng của bạn sẽ được hoàn thiện trọn vẹn nhờ chuỗi tiện ích đa dạng: nhà hàng nội khu ấm cúng phục vụ buffet sáng, quầy bar, phòng chờ chung rộng rãi và dịch vụ đưa đón sân bay chu đáo. Đây luôn là lựa chọn lưu trú lý tưởng cho những chuyến du lịch gia đình hoặc công tác nhờ chi phí hợp lý và dịch vụ tận tâm.","expectedPhotoFiles":["3S02_01.jpg","3S02_02.jpg","3S02_03.jpg"],"photos":[],"notes":["Chưa có ảnh Đà Lạt đã đối chiếu mã cơ sở trong các lượt bổ sung hiện tại.","Tọa độ lấy từ bảng khảo sát, chưa xác minh độc lập vị trí thực tế."]},{"id":"3S03","name":"Khách sạn Phố Núi Đà Lạt","group":"Khách sạn 3 sao","category":"3s","type":"Khách sạn","star":"3 sao","address":"Số 46 Đường Nguyễn Chí Thanh, Phường 1, TP. Đà Lạt","lat":11.9424,"lng":108.4367,"maps":"https://share.google/CL0oJ3tFQGQa6WjuF","description":"Khách sạn Phố Núi Đà Lạt (Pho Nui Hotel) là điểm lưu trú tiêu chuẩn 3 sao quen thuộc, tọa lạc đắc địa tại số 44-46 Nguyễn Chí Thanh, Phường 1. Nằm ngay trên ngọn đồi thoải ở trung tâm thành phố, khách sạn chỉ cách Chợ đêm Đà Lạt và hồ Xuân Hương khoảng 5 phút đi bộ, mở ra vị trí lý tưởng để du khách mua sắm, ăn uống và dạo phố dốc thơ mộng.\nNơi đây sở hữu phong cách kiến trúc hiện đại kết hợp hài hòa với những đường nét cổ kính phương Tây. Quy mô gồm 33 phòng nghỉ được thiết kế trang nhã, ấm cúng với nội thất gỗ tinh tế. Điểm nhấn đắt giá của Phố Núi là hệ thống cửa sổ kính lớn và ban công rộng thoáng, cho phép du khách phóng tầm mắt chiêm ngưỡng trọn vẹn toàn cảnh thành phố sương mù hoặc mặt hồ Xuân Hương phẳng lặng.\nTiện ích tại đây được hoàn thiện với nhà hàng phục vụ buffet sáng, quầy bar, dịch vụ spa thư giãn, bãi đậu xe miễn phí cùng đội ngũ nhân viên thân thiện, nhiệt tình.","expectedPhotoFiles":["3S03_01.jpg","3S03_02.jpg","3S03_03.jpg"],"photos":["data:image/jpeg;base64,","data:image/jpeg;base64,","data:image/jpeg;base64,","data:image/jpeg;base64,"],"notes":["Đã đưa 4 ảnh do người dùng cung cấp vào bản đồ.","Tọa độ lấy từ bảng khảo sát, chưa xác minh độc lập vị trí thực tế."]},{"id":"3S04","name":"Dalat Plaza Hotel","group":"Khách sạn 3 sao","category":"3s","type":"Khách sạn","star":"3 sao","address":"Số 19 Đường Lê Đại Hành, Phường 3, TP. Đà Lạt","lat":11.9402,"lng":108.4358,"maps":"https://share.google/ae7UnFO9t9IUrFthU","description":"Dalat Plaza Hotel (còn được biết đến với tên gọi cũ là Park Hotel Dalat) là khách sạn đạt tiêu chuẩn 3 sao quốc tế thanh lịch Dalat Plaza Hotel. Khách sạn tọa lạc tại số 19 Lê Đại Hành, Phường 3, sở hữu vị trí đắc địa ngay trung tâm thành phố, nằm sát bên Hồ Xuân Hương và công viên trung tâm, đồng thời chỉ cách Chợ Đà Lạt khoảng 5 phút đi bộ Khách sạn Park Dalat ( former Dalat Plaza Hotel) - Vntrip.vn.\nKhách sạn nổi bật với phong cách kiến trúc châu Âu kết hợp bài trí tân cổ điển tinh tế, hài hòa Khách sạn Đà Lạt Plaza - Sun Travel. Quy mô gồm 91 phòng nghỉ tiện nghi, đều được thiết kế cửa sổ kính lớn mở rộng tầm nhìn thoáng đãng hướng ra khung cảnh thành phố nhộn nhịp, công viên xanh mát hoặc mặt hồ thơ mộng Khách sạn Đà Lạt Plaza - Sun Travel.\nTrải nghiệm lưu trú tại đây được phục vụ chu đáo trọn vẹn nhờ chuỗi tiện ích đa dạng: nhà hàng nội khu ấm cúng cung cấp buffet sáng Khách sạn nhìn ra hồ có nhà hàng sang trọng, phòng thể hình, cung cấp Wi-Fi miễn phí, bữa sáng và chỗ đậu xe., dịch vụ massage và spa thư giãn Khách sạn Đà Lạt Plaza - Sun Travel, phòng tập thể dục, phòng karaoke giải trí cùng quầy lưu niệm tiện lợi Da Lat Plaza Hotel | địa chỉ, giá, tiện ích - The Best VN. Nơi đây luôn là sự lựa chọn hợp lý hàng đầu cho du khách nhờ chi phí tiết kiệm và vị trí kết nối muôn nơi Khách sạn Đà Lạt Plaza","expectedPhotoFiles":["3S04_01.jpg","3S04_02.jpg","3S04_03.jpg"],"photos":[],"notes":["Chưa có ảnh Đà Lạt đã đối chiếu mã cơ sở trong các lượt bổ sung hiện tại.","Tọa độ lấy từ bảng khảo sát, chưa xác minh độc lập vị trí thực tế."]},{"id":"3S05","name":"New Life Hotel Đà Lạt","group":"Khách sạn 3 sao","category":"3s","type":"Khách sạn","star":"3 sao","address":"Số 6 Đường Đống Đa, Phường 3, TP. Đà Lạt","lat":11.9248,"lng":108.4428,"maps":"https://share.google/AaN2Ddi4f3xELttBi","description":"New Life Hotel Đà Lạt là khách sạn tiêu chuẩn 3 sao hiện đại, tọa lạc tại số 6 Đường Đống Đa, Phường 3. Điểm đắt giá nhất của nơi đây chính là vị trí đắc địa trên một triền đồi cao, giúp lánh xa sự ồn ào phố thị nhưng vẫn đủ gần để du khách di chuyển đến trung tâm.\nKhách sạn sở hữu phong cách kiến trúc châu Âu trẻ trung, tinh tế. Quy mô gồm 66 phòng nghỉ được thiết kế hiện đại, ngập tràn ánh sáng tự nhiên. Phần lớn các hạng phòng tại đây đều được tích hợp ban công rộng thoáng hoặc cửa sổ lớn, mở ra tầm nhìn panorama tuyệt mỹ ôm trọn thung lũng thông xanh và cảnh sắc thành phố chuyển mình trong sương mờ hay ánh hoàng hôn.\nTiện ích của New Life Hotel được trang bị đồng bộ với nhà hàng ấm cúng phục vụ buffet, quán cà phê Catina ngắm cảnh, trung tâm Spa trị liệu cùng bãi đậu xe ô tô rất rộng rãi.","expectedPhotoFiles":["3S05_01.jpg","3S05_02.jpg","3S05_03.jpg"],"photos":["data:image/jpeg;base64,","data:image/jpeg;base64,","data:image/jpeg;base64,"],"notes":["Đã đưa 3 ảnh do người dùng cung cấp vào bản đồ.","Tọa độ lấy từ bảng khảo sát, chưa xác minh độc lập vị trí thực tế."]},{"id":"HS01","name":"Cú Trên Cây Homestay","group":"Homestay","category":"homestay","type":"Homestay","star":"Không áp dụng","address":"37 Đặng Thái Thân, Phường 3, TP. Đà Lạt.","lat":11.9287,"lng":108.4347,"maps":"https://share.google/tLSwyLMlFLn7Hh0Ff","description":"tọa lạc lưng chừng đồi tại số 37 Đặng Thái Thân, Phường 3 Cu Tren Cay Homestay, cách trung tâm Chợ Đà Lạt chỉ khoảng 2,5km Đôi nét về Cú Trên Cây Homestay. Nơi đây thu hút những tâm hồn mê xê dịch nhờ phong cách mộc mạc và không gian hòa mình trọn vẹn vào thiên nhiên xứ lạnh Review Cú Trên Cây homestay Đà Lạt thưởng view 360 độ ....\nHomestay được thiết kế tựa như một \"làng chim nhỏ\" chênh vênh giữa thung lũng sương mù Đôi nét về Cú Trên Cây Homestay. Các căn nhà gỗ đều được gọi bằng những cái tên đáng yêu như Tổ Cú, Tổ Chim Ri, Tổ Sóc hay Tổ Đại Bàng - Cú Trên Cây. Chúng được dựng từ các vật liệu tái chế, lợp mái nhiều tầng sáng tạo và sơn lối vintage màu sắc Review Cú Trên Cây homestay Đà Lạt thưởng view 360 độ ... Review Cú Trên Cây Homestay Đà Lạt siêu độc và lạ. Hầu hết các tổ đều sở hữu ban công view 360 độ nhìn thẳng ra thung lũng thông xanh phẳng lặng Review Cú Trên Cây homestay Đà Lạt thưởng view 360 độ ....\nTại nhà Cú, du khách sẽ được trải nghiệm các tiện ích bình yên như gian bếp chung để tự tay nấu nướng Review Cú Trên Cây Homestay Đà Lạt siêu độc và lạ, khoảng sân hiên ngắm mây bồng bềnh tổ chức tiệc BBQ Cú Trên Cây Homestay, Ấp Xuân An - Booking.com và một góc cà phê nhỏ ngập tràn hoa lá The moment you step into Cú Trên Cây Coffee, you are greeted by a lush, green environment that instantly soothes your senses. (2024-06-29).","expectedPhotoFiles":["HS01_01.jpg","HS01_02.jpg","HS01_03.jpg"],"photos":[],"notes":["Chưa có ảnh Đà Lạt đã đối chiếu mã cơ sở trong các lượt bổ sung hiện tại.","Tọa độ lấy từ bảng khảo sát, chưa xác minh độc lập vị trí thực tế."]},{"id":"HS02","name":"Đợi Một Người Homestay","group":"Homestay","category":"homestay","type":"Homestay","star":"Không áp dụng","address":"Tổ dân phố 65, khu vực đèo Prenn, Phường 3, TP. Đà Lạt.","lat":11.9059,"lng":108.4526,"maps":"https://share.google/INA5gA0QHzHKERAo7","description":"Đợi Một Người Homestay là chốn dừng chân đầy chất thơ, tọa lạc chênh vênh bên sườn đồi tại tổ 65, đường đèo Prenn, Phường 3, cách trung tâm thành phố khoảng 6km. Nơi đây đốn tim những tâm hồn mộng mơ nhờ không gian biệt lập, được bao bọc trọn vẹn bởi những rẫy cà phê xanh mướt và rừng thông bạt ngàn reo vui trong gió.\nHomestay sở hữu lối kiến trúc mộc mạc pha chút cổ điển phương Âu với tông màu trầm ấm áp. Hệ thống phòng nghỉ tại đây rất đa dạng, từ phòng áp mái ấm cúng, phòng Private tinh tế đến phòng gỗ Lake View lãng mạn, tất cả đều sử dụng hệ cửa kính lớn tối ưu tầm nhìn hướng thung lũng mờ sương.\nĐiểm nhấn đắt giá nhất của Đợi Một Người chính là ngôi nhà kính độc đáo nổi giữa lòng hồ nước, bao quanh bởi vườn hoa khoe sắc. Đây là không gian lý tưởng để bạn ngồi thưởng thức ly cà phê muối ấm nóng, đọc sách, ngắm mây trời bồng bềnh và tận hưởng nhịp sống chậm rãi, bình yên đúng nghĩa của xứ lạnh.","expectedPhotoFiles":["HS02_01.jpg","HS02_02.jpg","HS02_03.jpg"],"photos":[],"notes":["Chưa có ảnh Đà Lạt đã đối chiếu mã cơ sở trong các lượt bổ sung hiện tại.","Tọa độ lấy từ bảng khảo sát, chưa xác minh độc lập vị trí thực tế."]},{"id":"HS03","name":"LengKeng Da Lat Homestay","group":"Homestay","category":"homestay","type":"Homestay","star":"Không áp dụng","address":"57/4 Hoàng Hoa Thám, Phường 10, TP. Đà Lạt.","lat":11.9392,"lng":108.4597,"maps":"https://share.google/ht0k46l79QWPF0ekm","description":"LengKeng Da Lat Homestay là chốn dừng chân mộc mạc và an yên, tọa lạc tại số 57/4 Hoàng Hoa Thám, Phường 10, cách trung tâm thành phố chưa đầy 3km. Nằm trên một triền đồi cao lý tưởng, nơi đây mang đến không gian trốn phố về rừng đúng nghĩa với tầm nhìn panorama ôm trọn thung lũng bạt ngàn thông xanh và những làn mây bồng bềnh mỗi sớm mai.\nĐúng như tên gọi, điểm độc đáo của homestay là tiếng chuông gió Nhật Bản ngân vang khắp không gian, mang lại cảm giác thư thái, chữa lành. Hệ thống phòng tại LengKeng rất đa dạng, từ phòng trệt Bình Yên, phòng áp mái Hạnh Phúc đến các hạng phòng tập thể, được thiết kế ấm cúng với hệ cửa kính lớn hướng thung lũng.\nDu khách lưu trú tại đây sẽ được trải nghiệm các tiện ích thân thuộc như sân nướng BBQ ngắm hoàng hôn, gian bếp chung tự nấu nướng, nhà trà đạo thanh tịnh và vui chơi cùng những chú cún Corgi, mèo tam thể vô cùng đáng yêu.","expectedPhotoFiles":["HS03_01.jpg","HS03_02.jpg","HS03_03.jpg"],"photos":[],"notes":["Chưa có ảnh Đà Lạt đã đối chiếu mã cơ sở trong các lượt bổ sung hiện tại.","Tọa độ lấy từ bảng khảo sát, chưa xác minh độc lập vị trí thực tế."]},{"id":"HS04","name":"Củi Homestay","group":"Homestay","category":"homestay","type":"Homestay","star":"Không áp dụng","address":"79 Triệu Việt Vương, Phường 3, TP. Đà Lạt","lat":11.9216,"lng":108.4312,"maps":"https://share.google/8zTqKEPS3NpGiblTo","description":"Củi Homestay Đà Lạt là một \"xóm nhỏ\" mộc mạc và thanh bình, tọa lạc tại số 120 Đường Triệu Việt Vương, Phường 3 [DalatCuihomes], cách trung tâm thành phố chỉ khoảng 2,5km [Đà Lạt Củi Homestay | Đà Lạt]. Đúng như tên gọi, nơi đây mang đậm phong cách vintage hoài niệm với những căn nhà mái lá [Củi Homestay: Căn nhà mái lá bình yên ngập thiên nhiên ở Đà Lạt], tường vách gỗ thô mộc [Củi homestay được xây dựng bằng gỗ nâu, tre, nứa, mái lá,... giản dị và thân quen nằm ẩn giữa những khu vườn xanh mướt gợi cảm giác nhẹ ...] ẩn hiện giữa một khuôn viên ngập tràn cỏ hoa và những vườn hồng trĩu quả [Du lịch Đà Lạt tìm về chốn bình yên ở Củi Homestay - iVIVU.com].\nHệ thống lưu trú tại Củi rất đa dạng, từ phòng đơn ấm cúng [Đà Lạt Củi Homestay - Facebook], phòng đôi gác lửng Trăng Sao lãng mạn [Review Củi Homestay Đà Lạt - Focus Asia Travel, Đà Lạt Củi Homestay - Facebook] cho đến các căn nhà nguyên căn thích hợp cho nhóm bạn và gia đình [Đà Lạt Củi Homestay - Facebook]. Tất cả đều được thiết kế tối giản, lót chăn nệm êm ái [Củi Homestay Đà Lạt: Điểm dừng chân bình yên giữa lòng ...] và sở hữu cửa sổ lớn hướng thẳng ra khoảng sân vườn xanh mướt [“Củi Homestay Đà Lạt”: Có thật như lời đồn].\nTại đây, du khách sẽ được tận hưởng những tiện ích bình dị mà ấm áp như: tự tay nấu nướng tại gian bếp chung [Đà Lạt Củi Homestay | Đà Lạt], quây quần nhóm củi đốt lửa trại và tổ chức tiệc BBQ ngoài trời thả ga khi đêm về [Đà Lạt Củi Homestay - Facebook]. Ngoài ra, homestay còn ghi điểm tuyệt đối nhờ sự thân thiện của chủ nhà [Vườn Nhà Củi Homestay, Đà Lạt (cập nhật giá năm 2026)] cùng chính sách chào đón những bạn thú cưng đi cùng [Đà Lạt Củi Homestay | Đà Lạt].","expectedPhotoFiles":["HS04_01.jpg","HS04_02.jpg","HS04_03.jpg"],"photos":[],"notes":["Chưa có ảnh Đà Lạt đã đối chiếu mã cơ sở trong các lượt bổ sung hiện tại.","Tọa độ lấy từ bảng khảo sát, chưa xác minh độc lập vị trí thực tế."]},{"id":"HS05","name":"Sóc Homestay","group":"Homestay","category":"homestay","type":"Homestay","star":"Không áp dụng","address":"252 Hai Bà Trưng, Phường 6, TP. Đà Lạt.","lat":11.9478,"lng":108.4319,"maps":"https://share.google/IzXns9NlOCyu02xVw","description":"Sóc Homestay Đà Lạt (hay còn phổ biến với các tên gọi như Nhà của Sóc, Han's Sóc Homestay) là điểm dừng chân bình yên và ấm cúng, tọa lạc tại các vị trí đắc địa gần trung tâm thành phố như đường Trần Hưng Đạo hoặc Lý Tự Trọng. Nơi đây ghi điểm tuyệt đối trong lòng các tín đồ mê xê dịch nhờ tiêu chí \"Sạch thật - Chân thật - Chu đáo\" và mức giá vô cùng phải chăng.\nHomestay sở hữu không gian mang phong cách mộc mạc pha chút cổ điển, mang lại cảm giác thân thuộc như đang ở chính ngôi nhà thứ hai của mình. Hệ thống phòng nghỉ tại đây đa dạng, từ phòng đơn lãng mạn dành cho cặp đôi đến phòng đôi và nguyên căn rộng rãi dành cho nhóm bạn hay gia đình. Hầu hết các phòng đều được chăm chút tỉ mỉ, trang bị chăn nệm cao cấp êm ái, tích hợp cửa sổ lớn mở rộng tầm nhìn ôm trọn thung lũng mờ sương hay cảnh phố núi lung linh khi đêm về.\nTại nhà Sóc, du khách được tận hưởng đầy đủ tiện ích tiện nghi như gian bếp chung để tự tay nấu nướng, khoảng sân vườn xanh mát thích hợp để tổ chức những bữa tiệc BBQ ngoài trời. Đặc biệt, sự hiếu khách, hỗ trợ nhiệt tình từ chủ nhà càng làm cho kỳ nghỉ dưỡng của bạn thêm phần trọn vẹn.","expectedPhotoFiles":["HS05_01.jpg","HS05_02.jpg","HS05_03.jpg"],"photos":[],"notes":["Chưa có ảnh Đà Lạt đã đối chiếu mã cơ sở trong các lượt bổ sung hiện tại.","Tọa độ lấy từ bảng khảo sát, chưa xác minh độc lập vị trí thực tế."]}];
